// A autenticação é feita no nó "Mensagem recebida" (Header Auth: x-webhook-token).
// Eventos sem o token certo nem chegam aqui.

const INSTANCIA = 'assistente';   // fixa: não confia no nome de instância que vem no corpo

// 1) Pega os dados que a Evolution mandou
const body = $input.first().json.body || {};
const data = body.data || {};
const key = data.key || {};
const raw = key.remoteJid || '';

// 2) Ignora o que não é mensagem de uma pessoa pra você
if (body.event && body.event !== 'messages.upsert') return [];   // outros eventos
if (key.fromMe) return [];                                        // mensagem que VOCÊ mandou (evita loop)
if (!raw || raw.endsWith('@g.us') || raw.includes('broadcast') || raw.endsWith('@newsletter')) return []; // grupos, status, canais

// Contatos novos podem vir como "...@lid"; só aceita telefone válido (impede envio para destino forjado)
const jid = (raw.endsWith('@lid') && (key.remoteJidAlt || key.senderPn)) || raw;
if (!/^\d{8,15}@s\.whatsapp\.net$/.test(jid)) return [];

// 3) Data e hora de Brasília
const agora = new Date();
const hoje = new Intl.DateTimeFormat('en-CA', { timeZone: 'America/Sao_Paulo' }).format(agora); // AAAA-MM-DD
const hora = Number(new Intl.DateTimeFormat('en-US', { timeZone: 'America/Sao_Paulo', hour: 'numeric', hourCycle: 'h23' }).format(agora));

// 4) "Memória" do workflow: quem já recebeu a saudação hoje
//    (só persiste quando o workflow está PUBLICADO/ativo, não em testes manuais)
const memoria = $getWorkflowStaticData('global');
if (memoria.dia !== hoje) {        // virou o dia? zera a lista
  memoria.dia = hoje;
  memoria.contatos = {};
}
if (memoria.contatos[jid]) return [];  // já falou hoje -> para aqui
memoria.contatos[jid] = true;

// 5) Monta a saudação pelo horário
let saudacao = 'Boa noite';
if (hora >= 5 && hora < 12) saudacao = 'Bom dia';
else if (hora >= 12 && hora < 18) saudacao = 'Boa tarde';

const nome = (data.pushName || '').trim().split(' ')[0];
const texto = saudacao + (nome ? ', ' + nome : '') + '! 👋 Aqui é o assistente do Salatiel. Ele está ocupado no momento, mas em breve vai falar com você. 😊';

return [{ json: { numero: jid.split('@')[0], texto, instancia: INSTANCIA } }];
